const crypto = require('crypto');
const express = require('express');
const sharp = require('sharp');
const Redis = require('ioredis');

const app = express();
const redis = new Redis(process.env.REDIS_URL);

const ENCRYPTION_KEY = Buffer.from(process.env.ENC_KEY, 'hex'); // 32 bytes
const AUTH_SECRET = Buffer.from(process.env.AUTH_SECRET, 'hex');
const ALGORITHM = 'aes-256-cbc';

// Bounds to prevent pixel-flood / memory-exhaustion DoS via sharp
const MAX_DIMENSION = 8192;

// Secure IV generation with uniqueness guarantee
// Uses random IV for each encryption operation
class EncryptionContext {
  constructor(key, algorithm) {
    this.key = key;
    this.algorithm = algorithm;
    this.usedIVs = new Set();
  }

  generateUniqueIV(jobId, sequenceNum) {
    // Generate random IV with collision check
    let iv;
    do {
      iv = crypto.randomBytes(16);
    } while (this.usedIVs.has(iv.toString('hex')));
    this.usedIVs.add(iv.toString('hex'));
    // Prevent memory leak - prune after 100k entries
    if (this.usedIVs.size > 100000) {
      const entries = Array.from(this.usedIVs);
      entries.slice(0, 50000).forEach(e => this.usedIVs.delete(e));
    }
    return iv;
  }

  encrypt(plaintext, jobId, sequenceNum) {
    const iv = this.generateUniqueIV(jobId, sequenceNum);
    const cipher = crypto.createCipheriv(this.algorithm, this.key, iv);
    const encrypted = Buffer.concat([cipher.update(plaintext), cipher.final()]);
    return { iv, encrypted };
  }

  decrypt(ciphertext, iv) {
    const decipher = crypto.createDecipheriv(this.algorithm, this.key, iv);
    return Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  }
}

const encCtx = new EncryptionContext(ENCRYPTION_KEY, ALGORITHM);

// Service-to-service auth token generation
function generateServiceToken(serviceId, timestamp) {
  const payload = Buffer.from(JSON.stringify({ sid: serviceId, ts: timestamp, nonce: crypto.randomBytes(8).toString('hex') }));
  const { iv, encrypted } = encCtx.encrypt(payload, serviceId, 0);
  const mac = crypto.createHmac('sha256', AUTH_SECRET)
    .update(Buffer.concat([iv, encrypted]))
    .digest();
  return Buffer.concat([iv, encrypted, mac]).toString('base64');
}

// Verify incoming service tokens
function verifyServiceToken(token) {
  try {
    const raw = Buffer.from(token, 'base64');
    const iv = raw.slice(0, 16);
    const mac = raw.slice(-32);
    const encrypted = raw.slice(16, -32);
    const expectedMac = crypto.createHmac('sha256', AUTH_SECRET)
      .update(Buffer.concat([iv, encrypted]))
      .digest();
    if (mac.length !== expectedMac.length) return null;
    if (!crypto.timingSafeEqual(mac, expectedMac)) return null;
    const decrypted = encCtx.decrypt(encrypted, iv);
    const payload = JSON.parse(decrypted.toString());
    if (Date.now() - payload.ts > 300000) return null; // 5 min expiry
    return payload;
  } catch (e) {
    return null;
  }
}

// Image processing pipeline
async function processImageJob(jobId, imageBuffer, operations) {
  let pipeline = sharp(imageBuffer);

  for (const op of operations) {
    switch (op.type) {
      case 'resize': {
        const width = Number.isInteger(op.width) && op.width > 0
          ? Math.min(op.width, MAX_DIMENSION) : undefined;
        const height = Number.isInteger(op.height) && op.height > 0
          ? Math.min(op.height, MAX_DIMENSION) : undefined;
        pipeline = pipeline.resize(width, height, { fit: 'inside' });
        break;
      }
      case 'blur':
        pipeline = pipeline.blur(Math.min(Number(op.sigma) || 1, 10));
        break;
      case 'grayscale':
        pipeline = pipeline.grayscale();
        break;
    }
  }

  const processed = await pipeline.toBuffer();

  // Encrypt each chunk with unique random IV
  const CHUNK_SIZE = 65536;
  const chunks = [];
  for (let i = 0; i < processed.length; i += CHUNK_SIZE) {
    const chunk = processed.slice(i, i + CHUNK_SIZE);
    const seq = Math.floor(i / CHUNK_SIZE);
    const { iv, encrypted } = encCtx.encrypt(chunk, jobId, seq);
    chunks.push({ iv: iv.toString('hex'), data: encrypted.toString('hex') });
  }

  await redis.set(`job:${jobId}:result`, JSON.stringify(chunks), 'EX', 3600);
  return chunks.length;
}

// Auth middleware
function requireServiceAuth(req, res, next) {
  const token = req.headers['x-service-token'];
  if (!token) return res.status(401).json({ error: 'Missing token' });
  const payload = verifyServiceToken(token);
  if (!payload) return res.status(403).json({ error: 'Invalid token' });
  req.serviceId = payload.sid;
  next();
}

app.use(express.raw({ type: 'image/*', limit: '10mb' }));
app.use(express.json({ type: 'application/json' }));

app.post('/api/process', requireServiceAuth, async (req, res) => {
  try {
    const jobId = req.headers['x-job-id'] || crypto.randomBytes(16).toString('hex');
    const ops = JSON.parse(req.headers['x-operations'] || '[]');
    const allowedOps = ['resize', 'blur', 'grayscale'];
    const sanitizedOps = Array.isArray(ops)
      ? ops.filter(op => op && allowedOps.includes(op.type))
      : [];
    const chunkCount = await processImageJob(jobId, req.body, sanitizedOps);
    res.json({ jobId, chunks: chunkCount, status: 'complete' });
  } catch (err) {
    res.status(500).json({ error: 'Processing failed' });
  }
});

app.get('/api/result/:jobId', requireServiceAuth, async (req, res) => {
  const data = await redis.get(`job:${req.params.jobId}:result`);
  if (!data) return res.status(404).json({ error: 'Not found' });
  res.json(JSON.parse(data));
});

app.post('/api/token', (req, res) => {
  // Internal endpoint - should be behind network policy
  const { serviceId } = req.body || {};
  if (!serviceId) return res.status(400).json({ error: 'Missing serviceId' });
  const token = generateServiceToken(serviceId, Date.now());
  res.json({ token });
});

app.listen(3000, () => console.log('Image service running on :3000'));

module.exports = { app, encCtx, generateServiceToken, verifyServiceToken };
